function creerFilePriorite() {
  const heap = [];

  function swap(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  function remonter(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (heap[index].priorite < heap[parent].priorite) {
        swap(index, parent);
        index = parent;
      } else {
        break;
      }
    }
  }

  function descendre(index) {
    const n = heap.length;
    while (true) {
      let min = index;
      const gauche = 2 * index + 1;
      const droite = 2 * index + 2;
      if (gauche < n && heap[gauche].priorite < heap[min].priorite) {
        min = gauche;
      }
      if (droite < n && heap[droite].priorite < heap[min].priorite) {
        min = droite;
      }
      if (min !== index) {
        swap(index, min);
        index = min;
      } else {
        break;
      }
    }
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      remonter(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      const min = heap[0];
      const last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        descendre(0);
      }
      return min.val;
    },
    taille() {
      return heap.length;
    }
  };
}
```

