async function executerEnPool(taches, concurrence) {
  const resultats = new Array(taches.length);
  let index = 0;

  async function worker() {
    while (index < taches.length) {
      const i = index++;
      resultats[i] = await taches[i]();
    }
  }

  const workers = [];
  for (let i = 0; i < concurrence; i++) {
    workers.push(worker());
  }
  await Promise.all(workers);
  return resultats;
}
