  let termine = false;
  let erreur = null;

  return {
    next(val) {
      if (termine || erreur) return;
      for (const ab of abonnes) {
        ab.next && ab.next(val);
      }
    },
    error(err) {
      if (termine || erreur) return;
      erreur = err;
      for (const ab of abonnes) {
        ab.error && ab.error(err);
      }
      abonnes.clear();
    },
    complete() {
      if (termine || erreur) return;
      termine = true;
      for (const ab of abonnes) {
        ab.complete && ab.complete();
      }
      abonnes.clear();
    },
    subscribe({ next, error, complete } = {}) {
      const abonnement = { next, error, complete };
      abonnes.add(abonnement);
      return {
        unsubscribe() {
          abonnes.delete(abonnement);
        }
      };
    }
  };
}
