  let subscribers = [];
  let isClosed = false;
  let isErrored = false;
  let errorValue = null;
  return {
    next(val) {
      if (isClosed || isErrored) return;
      subscribers.forEach(sub => sub.next && sub.next(val));
    },
    error(err) {
      if (isClosed || isErrored) return;
      isErrored = true;
      errorValue = err;
      subscribers.forEach(sub => sub.error && sub.error(err));
      subscribers = [];
    },
    complete() {
      if (isClosed || isErrored) return;
      isClosed = true;
      subscribers.forEach(sub => sub.complete && sub.complete());
      subscribers = [];
