      if (isErrored) {
        observer.error && observer.error(errorValue);
        return;
      }
      subscribers.push(observer);
      return {
        unsubscribe() {
          const index = subscribers.indexOf(observer);
          if (index !== -1) {
            subscribers.splice(index, 1);
          }
        }
      };
    }
