function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed';
  let failureCount = 0;
  let lastFailureTime = 0;
  let inHalfOpen = false;

  return async function(...args) {
    if (state === 'open') {
      const now = Date.now();
      if (now - lastFailureTime < delaiResetMs) {
        throw new Error('Circuit is open');
      } else {
        state = 'half-open';
        inHalfOpen = true;
      }
    }

    if (state === 'half-open') {
      if (inHalfOpen) {
        inHalfOpen = false;
        try {
          const result = await fn.apply(this, args);
          state = 'closed';
          failureCount = 0;
          return result;
        } catch (e) {
          state = 'open';
          lastFailureTime = Date.now();
          throw e;
        }
      } else {
        throw new Error('Circuit is half-open, waiting for test');
      }
    }

    try {
      const result = await fn.apply(this, args);
      failureCount = 0;
      return result;
    } catch (e) {
      failureCount++;
      if (failureCount >= seuil) {
        state = 'open';
        lastFailureTime = Date.now();
      }
      throw e;
    }
  };
}
```

